from fastapi import APIRouter, HTTPException, Depends
from models import (
    ProjectCreateRequest, ProjectCreateResponse, ProjectStatusResponse,
    RequirementSubmitRequest, RequirementSubmitResponse,
    TeamConfigRequest, TeamConfigResponse,
    PRDConfirmRequest, PRDConfirmResponse,
    ArchitectureConfirmRequest, ArchitectureConfirmResponse,
    TestCaseConfirmRequest, TestCaseConfirmResponse,
    BugReport, FixRecord, TestResult
)
from typing import List
import uuid
from datetime import datetime

router = APIRouter()

# In-memory storage for demo purposes
projects = {}

@router.post("/projects", response_model=ProjectCreateResponse, tags=["Projects"])
async def create_project(request: ProjectCreateRequest):
    project_id = str(uuid.uuid4())
    projects[project_id] = {
        "id": project_id,
        "name": request.name,
        "status": "initialized",
        "requirements": None,
        "team": None,
        "prd": None,
        "architecture": None,
        "test_cases": None,
        "test_results": [],
        "bugs": [],
        "fix_records": [],
        "created_at": datetime.utcnow().isoformat()
    }
    return ProjectCreateResponse(project_id=project_id, status="created")

@router.post("/projects/{project_id}/requirements", response_model=RequirementSubmitResponse, tags=["Requirements"])
async def submit_requirement(project_id: str, request: RequirementSubmitRequest):
    if project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    projects[project_id]["requirements"] = request.text
    projects[project_id]["status"] = "requirement_submitted"
    return RequirementSubmitResponse(project_id=project_id, status="requirement_received", message="Requirement received. PRD generation in progress.")

@router.post("/projects/{project_id}/team", response_model=TeamConfigResponse, tags=["Team"])
async def configure_team(project_id: str, request: TeamConfigRequest):
    if project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    projects[project_id]["team"] = request.team_members
    projects[project_id]["status"] = "team_configured"
    return TeamConfigResponse(project_id=project_id, status="team_configured", message="Team configuration saved.")

@router.post("/projects/{project_id}/prd/confirm", response_model=PRDConfirmResponse, tags=["PRD"])
async def confirm_prd(project_id: str, request: PRDConfirmRequest):
    if project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    if not request.confirmed:
        return PRDConfirmResponse(project_id=project_id, status="prd_rejected", message="PRD rejected, please revise.")
    projects[project_id]["prd"] = request.prd_content
    projects[project_id]["status"] = "prd_confirmed"
    return PRDConfirmResponse(project_id=project_id, status="prd_confirmed", message="PRD confirmed. Proceeding to architecture design.")

@router.post("/projects/{project_id}/architecture/confirm", response_model=ArchitectureConfirmResponse, tags=["Architecture"])
async def confirm_architecture(project_id: str, request: ArchitectureConfirmRequest):
    if project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    if not request.confirmed:
        return ArchitectureConfirmResponse(project_id=project_id, status="architecture_rejected", message="Architecture rejected, please revise.")
    projects[project_id]["architecture"] = request.architecture_content
    projects[project_id]["status"] = "architecture_confirmed"
    return ArchitectureConfirmResponse(project_id=project_id, status="architecture_confirmed", message="Architecture confirmed. Proceeding to development.")

@router.post("/projects/{project_id}/testcases/confirm", response_model=TestCaseConfirmResponse, tags=["TestCases"])
async def confirm_test_cases(project_id: str, request: TestCaseConfirmRequest):
    if project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    if not request.confirmed:
        return TestCaseConfirmResponse(project_id=project_id, status="testcases_rejected", message="Test cases rejected, please revise.")
    projects[project_id]["test_cases"] = request.test_cases
    projects[project_id]["status"] = "testcases_confirmed"
    return TestCaseConfirmResponse(project_id=project_id, status="testcases_confirmed", message="Test cases confirmed. Proceeding to testing.")

@router.post("/projects/{project_id}/test/run", response_model=TestResult, tags=["Testing"])
async def run_tests(project_id: str):
    if project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    # Simulated test execution
    result = TestResult(
        project_id=project_id,
        passed=8,
        failed=2,
        total=10,
        pass_rate=80.0,
        details=[
            {"test_id": "TC001", "status": "pass"},
            {"test_id": "TC002", "status": "fail", "log": "AssertionError: expected 5 got 3"}
        ],
        executed_at=datetime.utcnow().isoformat()
    )
    projects[project_id]["test_results"].append(result)
    projects[project_id]["status"] = "test_executed"
    if result.pass_rate >= 100.0:
        projects[project_id]["status"] = "completed"
    return result

@router.post("/projects/{project_id}/bugs", response_model=BugReport, tags=["Bugs"])
async def report_bug(project_id: str, bug: BugReport):
    if project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    bug.bug_id = str(uuid.uuid4())
    bug.reported_at = datetime.utcnow().isoformat()
    projects[project_id]["bugs"].append(bug)
    projects[project_id]["status"] = "bug_reported"
    return bug

@router.post("/projects/{project_id}/fix", response_model=FixRecord, tags=["Fixes"])
async def apply_fix(project_id: str, fix: FixRecord):
    if project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    fix.fix_id = str(uuid.uuid4())
    fix.fixed_at = datetime.utcnow().isoformat()
    projects[project_id]["fix_records"].append(fix)
    projects[project_id]["status"] = "fix_applied"
    return fix

@router.get("/projects/{project_id}/status", response_model=ProjectStatusResponse, tags=["Projects"])
async def get_project_status(project_id: str):
    if project_id not in projects:
        raise HTTPException(status_code=404, detail="Project not found")
    proj = projects[project_id]
    return ProjectStatusResponse(
        project_id=proj["id"],
        name=proj["name"],
        status=proj["status"],
        test_results=proj["test_results"],
        bugs=proj["bugs"],
        fix_records=proj["fix_records"],
        created_at=proj["created_at"]
    )
